class Node:
    def __init__(self, value, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

def walk(node):
    if node is None:
        return []
    return walk(node.left) + [node.value] + walk(node.right)

print(walk(Node(2, Node(1), Node(3))))

class Base:
    def label(self):
        return 'base'

class Child(Base):
    def label(self):
        return super().label() + '-child'

print(Child().label(), isinstance(Child(), Base))

class Box:
    def __init__(self):
        self._value = 2
    @property
    def value(self):
        return self._value
    @value.setter
    def value(self, value):
        self._value = value * 2

b = Box()
b.value = 5
print(b.value)

def collect(a, b=2, *args, scale=1, **kwargs):
    return (a + b + sum(args)) * scale, sorted(kwargs.items())

print(collect(1, 3, 4, 5, scale=2, z=9, y=8))

class Countdown:
    def __init__(self, value):
        self.value = value
    def __iter__(self):
        return self
    def __next__(self):
        if self.value == 0:
            raise StopIteration
        self.value -= 1
        return self.value + 1

print(list(Countdown(3)))

